// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 timestamp) public {
        // Bound timestamp to reasonable values
        timestamp = bound(timestamp, block.timestamp + 1, block.timestamp + 1000);

        // Ensure block.number % 15 == 0 by advancing to next multiple of 15
        uint256 targetBlock = ((block.number / 15) + 1) * 15;
        vm.roll(targetBlock);
        vm.warp(timestamp);

        // Record caller's initial balance
        address caller = address(0x1234);
        vm.deal(caller, 100 ether);

        // Record initial contract balance
        uint256 initialContractBalance = address(c).balance;

        // Deal 10 ether to the contract for the call
        vm.deal(address(c), initialContractBalance + 10 ether);

        // Perform the call
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 ether}("");

        // Assert the call succeeded (reference must satisfy this)
        assertTrue(success, "Fallback call should succeed");

        // After a successful call with block.number % 15 == 0, 
        // the contract should transfer all its balance (for reference C)
        // For buggy version it only transfers 1 ether, so balance > 0
        // General rule: balance equals (initial + 10 ether) - transferred amount
        // For reference: transferred = address(c).balance before transfer
        // For buggy: transferred = 1 ether

        // The property: after the call, if block.number % 15 == 0 and 
        // msg.value == 10 ether and block.timestamp > pastBlockTime,
        // then the contract's balance MUST be strictly less than caller's balance + 10 ether
        // because reference transfers everything (balance goes to 0)
        // while buggy only transfers 1 ether (leaving 9+ ether)

        uint256 callerBalanceAfter = address(caller).balance;
        uint256 contractBalanceAfter = address(c).balance;

        // The reference C will have 0 balance after transfer (all balance sent)
        // The buggy M will have (initial + 10 ether - 1 ether) balance
        // So if contract balance < callerBalance + 10 ether, it's satisfied by both?
        // Actually we need a rule that reference satisfies but buggy doesn't

        // Key difference: In reference, ALL balance is transferred out
        // In buggy, only 1 ether is transferred out
        // So: reference balance == 0, buggy balance > 0
        assertTrue(contractBalanceAfter == 0, "Contract balance should be zero after transfer");
    }
}

